<?php /** @var array<string,mixed> $s */ /** @var ?array<string,mixed> $cycle */ /** @var list<array<string,mixed>> $payments */ /** @var list<array<string,mixed>> $history */ /** @var list<array<string,mixed>> $past */ /** @var list<array<string,mixed>> $reminders */
