<div class="page-head"><div><p class="eyebrow"><?= e(config("renewals.types.{$s['service_type']}", $s['service_type'])) ?> · <?= e($s['reference']) ?></p><h1><?= e($s['identifier']) ?></h1></div><a class="btn btn-ghost" href="/renewals">&larr; Services</a></div>
