    <dl class="detail-list"><dt>Activated</dt><dd><?= e(local_date($s['activated_on'])) ?></dd><dt>Renewal period</dt><dd><?= (int) $s['period_months'] ?> months</dd><dt>Cycle</dt><dd><?= (int) $s['cycle_no'] ?></dd>
        <?php if ($s['project_public_id']) : ?><dt>Project</dt><dd><a href="/projects/<?= e($s['project_public_id']) ?>"><?= e($s['project_code']) ?> · <?= e($s['project_title']) ?></a></dd><?php endif; ?>
