        <div><span class="muted">Period</span><br><?= (int) $cycle['period_months'] ?> months</div><div><span class="muted">Approved by</span><br><?= e($cycle['approved_by_name'] ?? '') ?><br><span class="muted"><?= e(local_time($cycle['approved_at'])) ?></span></div>
        <?php if ($cycle['invoice_ref']) : ?><div><span class="muted">Paid</span><br><?= e(money($cycle['paid_minor'])) ?> of <?= e(money($cycle['invoice_amount_minor'])) ?></div><?php endif; ?></div><?php endif; ?>
