    <?php if ($payments !== []) : ?><h3>Payments</h3><ul class="plain-list"><?php foreach ($payments as $p) : ?><li><?= e(money($p['amount_minor'])) ?> · <?= e(config("renewals.payment_methods.{$p['method']}", $p['method'])) ?> · <?= e($p['reference']) ?> · <?= e(local_date($p['received_on'])) ?> <span class="muted">(<?= e($p['recorded_by'] ?? '') ?>)</span></li><?php endforeach; ?></ul><?php endif; ?></div><?php endif; ?>

<?php // ---- actions by stage ---- ?>
<?php if ($can['manage'] && $next !== []) : ?><div class="panel"><h2>Move to the next stage</h2><form method="post" action="<?= e($url) ?>" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="status">
    <select name="status" aria-label="Next stage"><?php foreach ($next as $n) : ?><option value="<?= e($n) ?>"><?= e(config("renewals.statuses.{$n}", $n)) ?></option><?php endforeach; ?></select><button class="btn btn-ghost btn-sm" type="submit">Move</button></form><p class="muted">The scheduled task also does this automatically as the expiry approaches.</p></div><?php endif; ?>

