        <div class="field"><label for="pp">Renewal period</label><select id="pp" name="period_months"><?php foreach (config('renewals.periods') as $m) : ?><option value="<?= (int) $m ?>"<?= (int) $s['period_months'] === (int) $m ? ' selected' : '' ?>><?= (int) $m ?> months</option><?php endforeach; ?></select></div>
