<?php if ($st === 'approved_for_renewal' && $can['manage']) : ?><div class="panel"><h2>Record the invoice</h2><p class="muted">Issue the quotation or invoice in your billing process, then record its number here. The amount must equal the approved total <?= e(money($cycle['total_minor'] ?? 0)) ?>.</p>
    <form method="post" action="<?= e($url) ?>" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="invoice"><div class="field"><label for="qr">Quotation number (optional)</label><input id="qr" name="quotation_ref" maxlength="80" value="<?= e($v('quotation_ref')) ?>"></div>
        <div class="field"><label for="ir">Invoice number</label><input id="ir" name="invoice_ref" required maxlength="80" value="<?= e($v('invoice_ref')) ?>"></div><div class="field"><label for="ia">Invoice amount including tax (₹)</label><input id="ia" name="amount" required inputmode="decimal" value="<?= e($v('amount', number_format((int) ($cycle['total_minor'] ?? 0) / 100, 2, '.', ''))) ?>"></div>
