<?php if ($st === 'invoice_issued' && $can['manage']) : ?><div class="panel"><h2>Send to the client</h2><form method="post" action="<?= e($url) ?>" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="invoice_sent"><button class="btn btn-primary btn-sm" type="submit">Mark invoice as sent to the client</button></form></div><?php endif; ?>

<?php if (in_array($st, ['invoice_issued', 'awaiting_payment'], true) && $can['manage']) : ?><div class="panel"><h2>Record a payment</h2><p class="muted">Still due: <?= e(money($due)) ?>. Record only money that has actually arrived. <strong>Payment does not renew the service:</strong> the provider must confirm that separately.</p>
