        <div class="field"><label for="rpw">Your password</label><input id="rpw" name="confirm_password" type="password" required autocomplete="current-password"></div><div class="form-actions"><button class="btn btn-ghost btn-sm" type="submit">Void and revise</button></div></form></div><?php endif; ?>

<?php if ($st === 'payment_received' && $can['manage']) : ?><div class="panel"><h2>Provider renewal</h2><p class="muted">Payment is in (or nothing is owed). Now renew the service with <?= e($s['provider']) ?>, then record their confirmation.</p><form method="post" action="<?= e($url) ?>" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="start"><button class="btn btn-primary btn-sm" type="submit">I have started the renewal with the provider</button></form></div><?php endif; ?>
