        <div class="field"><label for="nx">New expiry date</label><input id="nx" name="new_expiry" type="date" required value="<?= e($v('new_expiry')) ?>"></div><div class="field"><label for="cpw">Your password</label><input id="cpw" name="confirm_password" type="password" required autocomplete="current-password"></div>
