<?php if ($can['manage'] && !in_array($st, ['cancelled'], true)) : ?><div class="panel"><h2>Edit</h2><form method="post" action="<?= e($url) ?>" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="edit">
