    <h3>Correct the expiry date</h3><form method="post" action="<?= e($url) ?>" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="expiry"><div class="field"><label for="ne2">New expiry date</label><input id="ne2" name="new_expiry" type="date" required></div>
