<div class="panel"><h2>Hold or cancel</h2>
    <?php if ($st === 'on_hold') : ?><form method="post" action="<?= e($url) ?>" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="release"><button class="btn btn-primary btn-sm" type="submit">Release the hold</button></form>
    <?php else : ?><form method="post" action="<?= e($url) ?>" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="hold"><div class="field"><label for="hr">Put on hold: reason (required)</label><input id="hr" name="reason" required minlength="10" maxlength="255"></div><div class="form-actions"><button class="btn btn-ghost btn-sm" type="submit">Put on hold</button></div></form><?php endif; ?>
    <?php if ($can['approve']) : ?><form method="post" action="<?= e($url) ?>" class="form-grid" data-confirm="Cancel this service permanently?"><?= csrf_field() ?><input type="hidden" name="action" value="cancel"><div class="field"><label for="cr2">Cancel permanently: reason (required)</label><input id="cr2" name="reason" required minlength="10" maxlength="255"></div>
