<?php if ($past !== []) : ?><div class="panel"><h2>Earlier renewals</h2><div class="table-wrap"><table class="table"><thead><tr><th>Cycle</th><th>From</th><th>New expiry</th><th class="num">Price</th><th>Invoice</th><th>Provider confirmation</th></tr></thead><tbody>
    <?php foreach ($past as $c) : ?><tr><td><?= (int) $c['cycle_no'] ?></td><td><?= e(local_date($c['from_expiry'])) ?></td><td><?= $c['new_expiry'] ? e(local_date($c['new_expiry'])) : '—' ?></td><td class="num"><?= $c['total_minor'] !== null ? e(money($c['total_minor'])) : '—' ?></td><td><?= e($c['invoice_ref'] ?? '—') ?></td>
