<div class="panel"><h2>History</h2><ol class="timeline"><?php foreach ($history as $h) : ?><li><strong><?= e(ucfirst(str_replace('_', ' ', $h['event']))) ?><?= $h['to_status'] && in_array($h['event'], ['status', 'approved', 'invoice', 'invoice_sent', 'payment', 'provider_started', 'renewed', 'hold', 'rejected', 'release', 'cancelled', 'expired', 'price_revision'], true) ? ': ' . e(config("renewals.statuses.{$h['to_status']}", $h['to_status'])) : '' ?></strong> <span class="muted"><?= e(local_time($h['created_at'])) ?> · <?= e($h['actor'] ?? 'scheduled task') ?></span><?php if ($h['note']) : ?><p class="prewrap"><?= e($h['note']) ?></p><?php endif; ?></li><?php endforeach; ?></ol></div>
<?php if ($reminders !== []) : ?><div class="panel"><h2>Reminders sent</h2><ul class="plain-list"><?php foreach ($reminders as $r) : ?><li><?= e(local_time($r['created_at'])) ?> · <?= e($r['audience']) ?> · <?= e(str_replace('_', ' ', $r['kind'])) ?> (<?= (int) $r['offset_days'] ?>) · <?= e(str_replace('_', ' ', $r['channel'])) ?> · <?= e(str_replace('_', ' ', $r['result'])) ?><?= (int) $r['attempts'] > 1 ? ' · ' . (int) $r['attempts'] . ' attempts' : '' ?></li><?php endforeach; ?></ul></div><?php endif; ?>
